        "content": "{% load static %}<!doctype html>\n<html lang=\"en\" data-theme=\"midnight\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>{{ app_name }}</title>\n    <script>try{document.documentElement.dataset.theme=localStorage.getItem('theme')||'midnight'}catch(e){}</script>\n    <!-- Tailwind (CDN) — colors read CSS vars so the palette re-themes everything. -->\n    <script src=\"https://cdn.tailwindcss.com\"></script>\n    <script>\n      tailwind.config = {\n        theme: {\n          extend: {\n            colors: {\n              bg: \"var(--bg)\", surface: \"var(--surface)\", surface2: \"var(--surface-2)\",\n              line: \"var(--line)\", ink: \"var(--ink)\", muted: \"var(--muted)\",\n              brand: \"var(--brand)\", \"brand-fg\": \"var(--brand-fg)\", accent: \"var(--accent)\",\n            },\n            fontFamily: { sans: [\"ui-sans-serif\", \"system-ui\", \"-apple-system\", \"Segoe UI\", \"Roboto\", \"Helvetica\", \"Arial\", \"sans-serif\"] },\n          },\n        },\n      };\n    </script>\n    <link rel=\"stylesheet\" href=\"{% static 'core/theme.css' %}\" />\n    <!-- HTMX (server-driven interactions) + Alpine (client sprinkles). -->\n    <script src=\"https://unpkg.com/htmx.org@2.0.4\"></script>\n    <script defer src=\"https://cdn.jsdelivr.net/npm/alpinejs@3.14.8/dist/cdn.min.js\"></script>\n  </head>\n  <body class=\"min-h-screen bg-bg font-sans text-ink antialiased\">\n    {% block body %}{% endblock %}\n    <script src=\"{% static 'core/app.js' %}\"></script>\n  </body>\n</html>\n"
