        "path": "core/templates/core/dashboard.html",
        "content": "{% extends \"core/shell.html\" %}\n{% block content %}\n<div class=\"mx-auto max-w-4xl space-y-6\">\n  <div>\n    <h1 class=\"text-2xl font-semibold text-ink\">Dashboard</h1>\n    <p class=\"text-sm text-muted\">Here&rsquo;s what&rsquo;s happening today.</p>\n  </div>\n  {# AI: relabel these for the app's real metrics (or remove). #}\n  <div class=\"grid gap-4 sm:grid-cols-2 lg:grid-cols-4\">\n    <div class=\"rounded-2xl border border-line bg-surface p-5\"><p class=\"text-sm text-muted\">Items</p><p class=\"mt-2 text-3xl font-semibold text-ink\">{{ items|length }}</p></div>\n    <div class=\"rounded-2xl border border-line bg-surface p-5\"><p class=\"text-sm text-muted\">Active</p><p class=\"mt-2 text-3xl font-semibold text-ink\">&mdash;</p></div>\n    <div class=\"rounded-2xl border border-line bg-surface p-5\"><p class=\"text-sm text-muted\">This week</p><p class=\"mt-2 text-3xl font-semibold text-ink\">&mdash;</p></div>\n    <div class=\"rounded-2xl border border-line bg-surface p-5\"><p class=\"text-sm text-muted\">Pending</p><p class=\"mt-2 text-3xl font-semibold text-ink\">&mdash;</p></div>\n  </div>\n  {# AI: BUILD THE APP'S MAIN FEATURE HERE. This HTMX list is the pattern: a form\n     hx-post → items_create view renders core/partials/_items.html → HTMX swaps #items.\n     {% csrf_token %} is required for Django POSTs. #}\n  <div class=\"rounded-2xl border border-line bg-surface p-5\">\n    <h2 class=\"text-lg font-semibold text-ink\">Items</h2>\n    <form hx-post=\"{% url 'items_create' %}\" hx-target=\"#items\" hx-swap=\"innerHTML\" hx-on::after-request=\"this.reset()\" class=\"mt-3 flex gap-2\">\n      {% csrf_token %}\n      <input name=\"name\" placeholder=\"Add an item&hellip;\" required\n        class=\"h-10 flex-1 rounded-xl border border-line bg-bg px-3 text-sm text-ink outline-none focus:border-brand\" />\n      <button class=\"h-10 rounded-xl bg-brand px-4 text-sm font-medium text-brand-fg hover:brightness-110\">Add</button>\n    </form>\n    <div id=\"items\" class=\"mt-4\">\n      {% include \"core/partials/_items.html\" %}\n    </div>\n  </div>\n</div>\n{% endblock %}\n"
