        "path": "core/templates/core/shell.html",
        "content": "{% extends \"core/base.html\" %}\n{# Authenticated app shell: sidebar + topbar around {% block content %}. #}\n{% block body %}\n<div class=\"flex min-h-screen bg-bg\">\n  {% include \"core/partials/_sidebar.html\" %}\n  <div class=\"flex min-w-0 flex-1 flex-col\">\n    {% include \"core/partials/_topbar.html\" %}\n    <main class=\"flex-1 p-6 md:p-8\">\n      {% block content %}{% endblock %}\n    </main>\n  </div>\n</div>\n{% endblock %}\n"
